using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.VertexAlgebra;

internal sealed class OriginalCurrentMetricDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/VertexAlgebra/OriginalCurrentMetric.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Original Current Positive Oscillator Metric",
        H("Original Current Positive Oscillator Metric"),
        Blocks(
            Paragraph(Text("Let D be the original LatticeData, with integral Gram matrix G and oscillator polynomial algebra Oscillator D. The sole metric assumption is hpos : (gramReal D).PosDef. Real spectral decomposition constructs S with S transpose times S equal to G, together with an explicit two-sided inverse. Multiplying S by the square root of k+1/2 at each natural mode gives a colour substitution and its inverse on the same polynomial algebra.")),
            Paragraph(Text("Pulling the factorial Fock form back along this algebra equivalence gives an InnerProductSpace.Core. The derived Gram law identifies the transformed positive current on generators; polynomial induction and Leibniz extend the identity to all states. The factorial creation/derivative pairing and Hermitian symmetry then give the original current formal adjoint at every integer j, with the mode reversed to -j-1. The form is conjugate linear first and linear second. All off-diagonal entries of G and rank zero are included.")),
            Paragraph(Text("Mathlib supplies the real Hermitian spectral theorem (Alexander Bentkamp and contributors, Apache 2.0), matrix identities, polynomial algebra, derivations and inner-product laws. The original half-mode architecture is due to Kalle Kytölä (2025), the additional actual half-integer implementation (2026), VirasoroProject and DN/BK/FLM; the corresponding operator sources carry their notices and licenses. Classical real spectral Gram/Bargmann Fock normalization carries no novelty claim. The factorial form and its creation/derivative pairing are those of FactorialFockMetric.")),
            Paragraph(Text("Second-slot additivity and scalar linearity follow by unfolding oscillatorInner and the factorial inner, then applying map_add/map_smul and inner_add_right/inner_smul_right. Strict positivity follows from re_inner_self_pos and injectivity of the factorial embedding composed with U.")),
            Paragraph(Text("For one-particle vectors, expand U(X(i,k)) and U(X(l,m)), distribute the finite sums, apply the factorial creation/derivative law and the vacuum monomial calculation, and use forward_gram. The result is zero when k differs from m and ((k:Complex)+1/2)*G(i,l) at equal modes, in the original colour order.")),
            Paragraph(Text("At rank zero, MvPolynomial.eq_C_of_isEmpty reduces every polynomial to its constant coefficient, which U.commutes fixes. The Core is still defined on that scalar polynomial algebra; current formulas indexed by Fin 0 have an empty colour telescope.")),
            Paragraph(Text("The pairing is an algebraic polynomial-domain identity. It does not assert physical/PCT or charged/ground unitarity, a maximal closed adjoint, bounded transport to the coefficient Hilbert space, or tensor, normal-sum and L0 identities. The frequency is the original half-integer j+1/2; the separate integer-neutral current is outside this statement.")),
            Node("gramReal", "gramReal",
                "The real Gram matrix is the entrywise real cast of the original integral G. Declaration: abbrev gramReal (D : LatticeData) : Matrix (Fin D.rank) (Fin D.rank) ℝ.", DescribeRole.Definition),
            Node("eigenvalue", "eigenvalue",
                "Eigenvalues are those of Mathlib’s Hermitian structure derived from positive definiteness. Declaration: def eigenvalue (D : LatticeData) (hpos : (gramReal D).PosDef) : Fin D.rank → ℝ.", DescribeRole.Definition),
            Node("Q", "Q",
                "The real eigenvector unitary is read from the same Hermitian spectral data. Declaration: def Q (D : LatticeData) (hpos : (gramReal D).PosDef) :\n    Matrix (Fin D.rank) (Fin D.rank) ℝ.", DescribeRole.Definition),
            Node("rootDiagonal", "rootDiagonal",
                "The diagonal contains the real square roots of the positive eigenvalues. Declaration: def rootDiagonal (D : LatticeData) (hpos : (gramReal D).PosDef) :\n    Matrix (Fin D.rank) (Fin D.rank) ℝ.", DescribeRole.Definition),
            Node("inverseRootDiagonal", "inverseRootDiagonal",
                "The inverse diagonal uses inverses of those square roots; nonzeroness is proved. Declaration: def inverseRootDiagonal (D : LatticeData) (hpos : (gramReal D).PosDef) :\n    Matrix (Fin D.rank) (Fin D.rank) ℝ.", DescribeRole.Definition),
            Node("S", "S",
                "New-colour rows and original-colour columns are obtained as rootDiagonal times Q transpose. Declaration: def S (D : LatticeData) (hpos : (gramReal D).PosDef) :\n    Matrix (Fin D.rank) (Fin D.rank) ℝ.", DescribeRole.Definition),
            Node("R", "R",
                "The explicit inverse is Q times inverseRootDiagonal. Declaration: def R (D : LatticeData) (hpos : (gramReal D).PosDef) :\n    Matrix (Fin D.rank) (Fin D.rank) ℝ.", DescribeRole.Definition),
            Node("eigenvalue_pos", "eigenvalue pos",
                "Mathlib Matrix.PosDef.eigenvalues_pos supplies strict positivity for the square-root arguments. Declaration: theorem eigenvalue_pos (D : LatticeData) (hpos : (gramReal D).PosDef)\n    (a : Fin D.rank) : 0 < eigenvalue D hpos a.", DescribeRole.Theorem),
            Node("root_eigenvalue_ne_zero", "root eigenvalue ne zero",
                "Real.sqrt_pos and strict eigenvalue positivity discharge the diagonal inverse denominators. Declaration: theorem root_eigenvalue_ne_zero (D : LatticeData) (hpos : (gramReal D).PosDef)\n    (a : Fin D.rank) : Real.sqrt (eigenvalue D hpos a) ≠ 0.", DescribeRole.Theorem),
            Node("Q_transpose_mul", "Q transpose mul",
                "Unitary.coe_star_mul_self over the real matrix gives the first orthogonality direction. Declaration: theorem Q_transpose_mul (D : LatticeData) (hpos : (gramReal D).PosDef) :\n    (Q D hpos)ᵀ * Q D hpos = 1.", DescribeRole.Theorem),
            Node("Q_mul_transpose", "Q mul transpose",
                "Unitary.coe_mul_star_self gives the second orthogonality direction. Declaration: theorem Q_mul_transpose (D : LatticeData) (hpos : (gramReal D).PosDef) :\n    Q D hpos * (Q D hpos)ᵀ = 1.", DescribeRole.Theorem),
            Node("spectral_factorization", "spectral factorization",
                "Mathlib’s Hermitian spectral theorem reconstructs the original Gram matrix from Q and its eigenvalues. Declaration: theorem spectral_factorization (D : LatticeData) (hpos : (gramReal D).PosDef) :\n    Q D hpos * Matrix.diagonal (eigenvalue D hpos) * (Q D hpos)ᵀ =\n      gramReal D.", DescribeRole.Theorem),
            Node("rootDiagonal_square", "rootDiagonal square",
                "Matrix.diagonal_mul_diagonal and Real.mul_self_sqrt compute the square. Declaration: theorem rootDiagonal_square (D : LatticeData) (hpos : (gramReal D).PosDef) :\n    rootDiagonal D hpos * rootDiagonal D hpos =\n      Matrix.diagonal (eigenvalue D hpos).", DescribeRole.Theorem),
            Node("rootDiagonal_inverse", "rootDiagonal inverse",
                "Pointwise mul_inv_cancel₀ gives the first diagonal inverse law. Declaration: theorem rootDiagonal_inverse (D : LatticeData) (hpos : (gramReal D).PosDef) :\n    rootDiagonal D hpos * inverseRootDiagonal D hpos = 1.", DescribeRole.Theorem),
            Node("inverse_rootDiagonal", "inverse rootDiagonal",
                "Pointwise inv_mul_cancel₀ gives the reverse diagonal inverse law. Declaration: theorem inverse_rootDiagonal (D : LatticeData) (hpos : (gramReal D).PosDef) :\n    inverseRootDiagonal D hpos * rootDiagonal D hpos = 1.", DescribeRole.Theorem),
            Node("S_transpose_mul", "S transpose mul",
                "The required covariance orientation S transpose times S equals G is derived by the spectral theorem. Declaration: theorem S_transpose_mul (D : LatticeData) (hpos : (gramReal D).PosDef) :\n    (S D hpos)ᵀ * S D hpos = gramReal D.", DescribeRole.Theorem),
            Node("S_mul_R", "S mul R",
                "The forward inverse law follows by orthogonality and the diagonal cancellation. Declaration: theorem S_mul_R (D : LatticeData) (hpos : (gramReal D).PosDef) :\n    S D hpos * R D hpos = 1.", DescribeRole.Theorem),
            Node("R_mul_S", "R mul S",
                "The reverse inverse law follows by the opposite diagonal cancellation and orthogonality. Declaration: theorem R_mul_S (D : LatticeData) (hpos : (gramReal D).PosDef) :\n    R D hpos * S D hpos = 1.", DescribeRole.Theorem),
            Node("SC", "SC",
                "The real mixing matrix is mapped to Complex through Complex.ofRealHom. Declaration: def SC (D : LatticeData) (hpos : (gramReal D).PosDef) :\n    Matrix (Fin D.rank) (Fin D.rank) ℂ.", DescribeRole.Definition),
            Node("RC", "RC",
                "The explicit real inverse is mapped through the same complex ring homomorphism. Declaration: def RC (D : LatticeData) (hpos : (gramReal D).PosDef) :\n    Matrix (Fin D.rank) (Fin D.rank) ℂ.", DescribeRole.Definition),
            Node("SC_mul_RC", "SC mul RC",
                "Mapping the already proved real forward inverse law gives complex cancellation. Declaration: theorem SC_mul_RC (D : LatticeData) (hpos : (gramReal D).PosDef) :\n    SC D hpos * RC D hpos = 1.", DescribeRole.Theorem),
            Node("RC_mul_SC", "RC mul SC",
                "Mapping the reverse real law gives the reverse complex cancellation. Declaration: theorem RC_mul_SC (D : LatticeData) (hpos : (gramReal D).PosDef) :\n    RC D hpos * SC D hpos = 1.", DescribeRole.Theorem),
            Node("SC_gram", "SC gram",
                "Entrywise extraction of S transpose times S and exact casts retain every off-diagonal original G entry. Declaration: theorem SC_gram (D : LatticeData) (hpos : (gramReal D).PosDef)\n    (i l : Fin D.rank) :\n    (∑ a : Fin D.rank, SC D hpos a i * SC D hpos a l) = (D.G i l : ℂ).", DescribeRole.Theorem),
            Node("modeReal", "modeReal",
                "The physical positive half-mode is k plus one half in real scalars. Declaration: def modeReal (k : ℕ) : ℝ.", DescribeRole.Definition),
            Node("modeScale", "modeScale",
                "The complex scale is the real square root of the positive half-mode. Declaration: def modeScale (k : ℕ) : ℂ.", DescribeRole.Definition),
            Node("modeReal_pos", "modeReal pos",
                "Every natural k gives a strictly positive real half-mode. Declaration: theorem modeReal_pos (k : ℕ) : 0 < modeReal k.", DescribeRole.Theorem),
            Node("modeScale_ne_zero", "modeScale ne zero",
                "Positivity of the real square root proves the complex scale is nonzero. Declaration: theorem modeScale_ne_zero (k : ℕ) : modeScale k ≠ 0.", DescribeRole.Theorem),
            Node("modeScale_square", "modeScale square",
                "The square of the real-derived complex scale is k plus one half. Declaration: theorem modeScale_square (k : ℕ) : modeScale k * modeScale k = (k : ℂ) + 1 / 2.", DescribeRole.Theorem),
            Node("forwardMatrix", "forwardMatrix",
                "The same-mode colour matrix has entries modeScale(k) times SC(a,i). Declaration: def forwardMatrix (D : LatticeData) (hpos : (gramReal D).PosDef) (k : ℕ) :\n    Matrix (Fin D.rank) (Fin D.rank) ℂ.", DescribeRole.Definition),
            Node("inverseMatrix", "inverseMatrix",
                "The inverse has original-colour row i, new-colour column a, inverse scale and RC(i,a). Declaration: def inverseMatrix (D : LatticeData) (hpos : (gramReal D).PosDef) (k : ℕ) :\n    Matrix (Fin D.rank) (Fin D.rank) ℂ.", DescribeRole.Definition),
            Node("forward_inverse", "forward inverse",
                "Finite matrix multiplication separates the scale cancellation from SC times RC. Declaration: theorem forward_inverse (D : LatticeData) (hpos : (gramReal D).PosDef) (k : ℕ) :\n    forwardMatrix D hpos k * inverseMatrix D hpos k = 1.", DescribeRole.Theorem),
            Node("inverse_forward", "inverse forward",
                "The reverse finite matrix product separates the inverse scale cancellation from RC times SC. Declaration: theorem inverse_forward (D : LatticeData) (hpos : (gramReal D).PosDef) (k : ℕ) :\n    inverseMatrix D hpos k * forwardMatrix D hpos k = 1.", DescribeRole.Theorem),
            Node("variableImage", "variableImage",
                "Finite colour mixing stays at the same natural mode and in the same polynomial ring. Declaration: def variableImage (A : ℕ → Matrix n n ℂ) (x : n × ℕ) :\n    MvPolynomial (n × ℕ) ℂ. Section context: universe u; variable {n : Type u} [Fintype n] [DecidableEq n].", DescribeRole.Definition),
            Node("substitution", "substitution",
                "Mathlib MvPolynomial.aeval extends the actual finite variable images as an algebra homomorphism. Declaration: def substitution (A : ℕ → Matrix n n ℂ) :\n    MvPolynomial (n × ℕ) ℂ →ₐ[ℂ] MvPolynomial (n × ℕ) ℂ. Section context: universe u; variable {n : Type u} [Fintype n] [DecidableEq n].", DescribeRole.Definition),
            Node("substitution_X", "substitution X",
                "Mathlib aeval_X computes a generator image for composition and U. Declaration: theorem substitution_X (A : ℕ → Matrix n n ℂ) (x : n × ℕ) :\n    substitution A (X x) = variableImage A x. Section context: universe u; variable {n : Type u} [Fintype n] [DecidableEq n].", DescribeRole.Theorem),
            Node("variableImage_one", "variableImage one",
                "The identity matrix gives the original generator by a finite delta sum. Declaration: theorem variableImage_one (x : n × ℕ) :\n    variableImage (fun _ => (1 : Matrix n n ℂ)) x = X x. Section context: universe u; variable {n : Type u} [Fintype n] [DecidableEq n].", DescribeRole.Theorem),
            Node("substitution_variableImage", "substitution variableImage",
                "Finite sum interchange proves the exact matrix composition order before polynomial freeness is used. Declaration: theorem substitution_variableImage (A B : ℕ → Matrix n n ℂ) (x : n × ℕ) :\n    substitution A (variableImage B x) =\n      variableImage (fun k => A k * B k) x. Section context: universe u; variable {n : Type u} [Fintype n] [DecidableEq n].", DescribeRole.Theorem),
            Node("substitution_comp", "substitution comp",
                "Polynomial algebra-homomorphism extensionality extends that generator computation to composition. Declaration: theorem substitution_comp (A B : ℕ → Matrix n n ℂ) :\n    (substitution A).comp (substitution B) =\n      substitution (fun k => A k * B k). Section context: universe u; variable {n : Type u} [Fintype n] [DecidableEq n].", DescribeRole.Theorem),
            Node("substitution_one", "substitution one",
                "Polynomial extensionality identifies identity-matrix substitution with AlgHom.id. Declaration: theorem substitution_one :\n    substitution (fun _ => (1 : Matrix n n ℂ)) =\n      AlgHom.id ℂ (MvPolynomial (n × ℕ) ℂ). Section context: universe u; variable {n : Type u} [Fintype n] [DecidableEq n].", DescribeRole.Theorem),
            Node("substitution_inverse", "substitution inverse",
                "The generic derived composition formula turns a matrix inverse law into homomorphism cancellation. Declaration: theorem substitution_inverse (A B : ℕ → Matrix n n ℂ)\n    (hAB : ∀ k, A k * B k = 1) :\n    (substitution A).comp (substitution B) =\n      AlgHom.id ℂ (MvPolynomial (n × ℕ) ℂ). Section context: universe u; variable {n : Type u} [Fintype n] [DecidableEq n].", DescribeRole.Theorem),
            Node("substitutionEquiv", "substitutionEquiv",
                "AlgEquiv.ofAlgHom packages the two generic inverse homomorphisms. Only this generic construction has inverse hypotheses. Declaration: def substitutionEquiv (A B : ℕ → Matrix n n ℂ)\n    (hAB : ∀ k, A k * B k = 1) (hBA : ∀ k, B k * A k = 1) :\n    MvPolynomial (n × ℕ) ℂ ≃ₐ[ℂ] MvPolynomial (n × ℕ) ℂ. Section context: universe u; variable {n : Type u} [Fintype n] [DecidableEq n].", DescribeRole.Definition),
            Node("lowering", "lowering",
                "A finite weighted sum of Mathlib partial derivations defines the actual polynomial lowering derivation. Declaration: def lowering (A : ℕ → Matrix n n ℂ) (i : n) (k : ℕ) :\n    Derivation ℂ (MvPolynomial (n × ℕ) ℂ) (MvPolynomial (n × ℕ) ℂ). Section context: universe u; variable {n : Type u} [Fintype n] [DecidableEq n].", DescribeRole.Definition),
            Node("lowering_apply", "lowering apply",
                "Derivation.coeFnAddMonoidHom and finite-sum linearity expose the exact weighted derivative. Declaration: theorem lowering_apply (A : ℕ → Matrix n n ℂ) (i : n) (k : ℕ)\n    (p : MvPolynomial (n × ℕ) ℂ) :\n    lowering A i k p = ∑ a : n, A k a i • MvPolynomial.pderiv (a, k) p. Section context: universe u; variable {n : Type u} [Fintype n] [DecidableEq n].", DescribeRole.Theorem),
            Node("lowering_X", "lowering X",
                "The partial derivative delta law evaluates lowering on every colour and mode generator. Declaration: theorem lowering_X (A : ℕ → Matrix n n ℂ) (i l : n) (k m : ℕ) :\n    lowering A i k (X (l, m)) =\n      if k = m then A k l i • (1 : MvPolynomial (n × ℕ) ℂ) else 0. Section context: universe u; variable {n : Type u} [Fintype n] [DecidableEq n].", DescribeRole.Theorem),
            Node("lowering_variableImage", "lowering variableImage",
                "The resulting generator pairing is the finite column Gram sum when the modes agree, and zero otherwise. Declaration: theorem lowering_variableImage (A : ℕ → Matrix n n ℂ)\n    (i l : n) (k m : ℕ) :\n    lowering A i k (variableImage A (l, m)) =\n      if k = m then (∑ a : n, A k a i * A k a l) •\n        (1 : MvPolynomial (n × ℕ) ℂ) else 0. Section context: universe u; variable {n : Type u} [Fintype n] [DecidableEq n].", DescribeRole.Theorem),
            Node("U", "U",
                "The forward algebra equivalence is on the exact original Oscillator D; the two inverse hypotheses are discharged by proved Gram identities. Declaration: def U (D : LatticeData) (hpos : (gramReal D).PosDef) :\n    Oscillator D ≃ₐ[ℂ] Oscillator D.", DescribeRole.Definition),
            Node("U_X", "U X",
                "Every original generator is sent to the explicit finite same-mode sum with original-colour column i. Declaration: theorem U_X (D : LatticeData) (hpos : (gramReal D).PosDef)\n    (i : Fin D.rank) (k : ℕ) :\n    U D hpos (X (i, k)) =\n      ∑ a : Fin D.rank, (modeScale k * (S D hpos a i : ℂ)) • X (a, k).", DescribeRole.Theorem),
            Node("conj_forwardMatrix", "conj forwardMatrix",
                "All mixing coefficients are complex images of real scalars, so conjugation fixes them. Declaration: theorem conj_forwardMatrix (D : LatticeData) (hpos : (gramReal D).PosDef)\n    (k : ℕ) (a i : Fin D.rank) :\n    conj (forwardMatrix D hpos k a i) = forwardMatrix D hpos k a i.", DescribeRole.Theorem),
            Node("forward_gram", "forward gram",
                "The finite forward coefficient Gram sum is frequency(k) times the original G(i,l). This is a conclusion, not a premise. Declaration: theorem forward_gram (D : LatticeData) (hpos : (gramReal D).PosDef)\n    (k : ℕ) (i l : Fin D.rank) :\n    (∑ a : Fin D.rank, forwardMatrix D hpos k a i * forwardMatrix D hpos k a l) =\n      frequency (k : ℤ) * (D.G i l : ℂ).", DescribeRole.Theorem),
            Node("positiveDerivation", "positiveDerivation",
                "The original Gram annihilation derivation is multiplied by the physical half-mode frequency. Declaration: def positiveDerivation (D : LatticeData) (i : Fin D.rank) (k : ℕ) :\n    Derivation ℂ (Oscillator D) (Oscillator D).", DescribeRole.Definition),
            Node("positiveDerivation_current", "positiveDerivation current",
                "The original nonnegative current definition is exactly this derivation on arbitrary polynomials. Declaration: theorem positiveDerivation_current (D : LatticeData) (i : Fin D.rank) (k : ℕ)\n    (p : Oscillator D) : positiveDerivation D i k p = current D i (k : ℤ) p.", DescribeRole.Theorem),
            Node("positiveDerivation_X", "positiveDerivation X",
                "The original annihilation generator law supplies frequency(k) times G(i,l) at equal modes. Declaration: theorem positiveDerivation_X (D : LatticeData) (i l : Fin D.rank) (k m : ℕ) :\n    positiveDerivation D i k (X (l, m)) =\n      if k = m then (frequency (k : ℤ) * (D.G i l : ℂ)) •\n        (1 : Oscillator D) else 0.", DescribeRole.Theorem),
            Node("lowering_U_X", "lowering U X",
                "The proved forward Gram law gives the annihilation intertwiner on every original generator. Declaration: theorem lowering_U_X (D : LatticeData) (hpos : (gramReal D).PosDef)\n    (i l : Fin D.rank) (k m : ℕ) :\n    lowering (forwardMatrix D hpos) i k (U D hpos (X (l, m))) =\n      U D hpos (positiveDerivation D i k (X (l, m))).", DescribeRole.Theorem),
            Node("U_positiveDerivation", "U positiveDerivation",
                "Polynomial induction with constants, addition and the actual Leibniz rule extends the intertwiner to every state. Declaration: theorem U_positiveDerivation (D : LatticeData) (hpos : (gramReal D).PosDef)\n    (i : Fin D.rank) (k : ℕ) (p : Oscillator D) :\n    U D hpos (positiveDerivation D i k p) =\n      lowering (forwardMatrix D hpos) i k (U D hpos p).", DescribeRole.Theorem),
            Node("oscillatorInner", "oscillatorInner",
                "Pull back the complete factorial form through U; this does not use the unweighted coefficient metric. Declaration: def oscillatorInner (D : LatticeData) (hpos : (gramReal D).PosDef)\n    (p q : Oscillator D) : ℂ.", DescribeRole.Definition),
            Node("oscillatorInner_conj_swap", "oscillatorInner conj swap",
                "Mathlib inner_conj_symm on actual embedded U-images gives Hermitian symmetry. Declaration: theorem oscillatorInner_conj_swap (D : LatticeData) (hpos : (gramReal D).PosDef)\n    (p q : Oscillator D) : conj (oscillatorInner D hpos q p) =\n      oscillatorInner D hpos p q.", DescribeRole.Theorem),
            Node("oscillatorInner_add_first", "oscillatorInner add first",
                "Linearity of U and factorial additivity supply the Core additivity field. Declaration: theorem oscillatorInner_add_first (D : LatticeData) (hpos : (gramReal D).PosDef)\n    (p q r : Oscillator D) : oscillatorInner D hpos (p + q) r =\n      oscillatorInner D hpos p r + oscillatorInner D hpos q r.", DescribeRole.Theorem),
            Node("oscillatorInner_smul_first", "oscillatorInner smul first",
                "Linearity of both embeddings and root inner_smul_left give conjugate first-slot scalar multiplication. Declaration: theorem oscillatorInner_smul_first (D : LatticeData) (hpos : (gramReal D).PosDef)\n    (c : ℂ) (p q : Oscillator D) : oscillatorInner D hpos (c • p) q =\n      conj c * oscillatorInner D hpos p q.", DescribeRole.Theorem),
            Node("oscillatorCore", "oscillatorCore",
                "The exact original oscillator carrier gets an InnerProductSpace.Core. Nonnegativity and definiteness use the factorial Core and U injectivity; no desired positivity is assumed. Declaration: def oscillatorCore (D : LatticeData) (hpos : (gramReal D).PosDef) :\n    InnerProductSpace.Core ℂ (Oscillator D).", DescribeRole.Definition),
            Node("factorial_variable_lowering_pairing", "factorial variable lowering pairing",
                "Distribute the finite creation and derivative sums, apply Mathlib sesquilinearity, and use the factorial all-polynomial pairing. Declaration: theorem factorial_variable_lowering_pairing (D : LatticeData)\n    (hpos : (gramReal D).PosDef) (i : Fin D.rank) (k : ℕ)\n    (p q : Oscillator D) :\n    D5.S3.VertexAlgebra.FactorialFockMetric.inner\n        (variableImage (forwardMatrix D hpos) (i, k) * p) q =\n      D5.S3.VertexAlgebra.FactorialFockMetric.inner p\n        (lowering (forwardMatrix D hpos) i k q).", DescribeRole.Theorem),
            Node("oscillator_negative_positive_pairing", "oscillator negative positive pairing",
                "Transport the actual original negative multiplication current through U and pair it with the original positive derivation on arbitrary states. Declaration: theorem oscillator_negative_positive_pairing (D : LatticeData)\n    (hpos : (gramReal D).PosDef) (i : Fin D.rank) (k : ℕ)\n    (p q : Oscillator D) :\n    oscillatorInner D hpos (current D i (-(k : ℤ) - 1) p) q =\n      oscillatorInner D hpos p (current D i (k : ℤ) q).", DescribeRole.Theorem),
            Node("oscillator_positive_negative_pairing", "oscillator positive negative pairing",
                "Hermitian symmetry reverses the proved original negative/positive pairing with the correct scalar convention. Declaration: theorem oscillator_positive_negative_pairing (D : LatticeData)\n    (hpos : (gramReal D).PosDef) (i : Fin D.rank) (k : ℕ)\n    (p q : Oscillator D) :\n    oscillatorInner D hpos (current D i (k : ℤ) p) q =\n      oscillatorInner D hpos p (current D i (-(k : ℤ) - 1) q).", DescribeRole.Theorem),
            Node("oscillator_current_pairing", "oscillator current pairing",
                "For every original D, positive Gram hpos, original colour i, integer mode j and arbitrary p,q, the formal algebraic adjoint is the original current at -j-1. Integer sign cases use the two half-mode laws; no desired pairing is an input. Declaration: theorem oscillator_current_pairing (D : LatticeData) (hpos : (gramReal D).PosDef)\n    (i : Fin D.rank) (j : ℤ) (p q : Oscillator D) :\n    (oscillatorCore D hpos).inner (current D i j p) q =\n      (oscillatorCore D hpos).inner p (current D i (-j - 1) q).", DescribeRole.Theorem)),
        []));

    private static DocumentBlock Node(string name, string title, string prose, DescribeRole role) =>
        Describe.Lean(DescribeId.Create("originalcurrentmetric-" + name.Replace("_", "-").ToLowerInvariant()), DeclarationHandle.Create(Prefix + name),
            H(title), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text(prose.Replace("\n", " ")))), role);
}
